#!/usr/bin/env bash
# Create the Kubernetes Secrets used by deploy/k3s/fleetops.yaml from the files in deploy/secrets
# (generated by `python scripts/provision.py`). Idempotent. Usage: scripts/k8s_secrets.sh [namespace]
set -euo pipefail
NS="${1:-fleetops}"
DIR="${SECRETS_DIR:-deploy/secrets}"
kubectl create namespace "$NS" --dry-run=client -o yaml | kubectl apply -f -

apply() { kubectl -n "$NS" create secret generic "$@" --dry-run=client -o yaml | kubectl apply -f -; }

apply fleetops-secrets \
  --from-file=fleetops_admin_api_key="$DIR/fleetops_admin_api_key" \
  --from-file=fleetops_operator_api_key="$DIR/fleetops_operator_api_key" \
  --from-file=fleetops_viewer_api_key="$DIR/fleetops_viewer_api_key" \
  --from-file=fleetops_device_key_master="$DIR/fleetops_device_key_master" \
  --from-file=fleetops_mqtt_password="$DIR/fleetops_mqtt_password" \
  --from-file=fleetops_mlflow_password="$DIR/fleetops_mlflow_password" \
  --from-file=fleetops_metrics_token="$DIR/fleetops_metrics_token"
apply mlflow-secrets \
  --from-file=mlflow_admin_password="$DIR/mlflow_admin_password" \
  --from-file=mlflow_flask_secret="$DIR/mlflow_flask_secret"
apply fleetops-mqtt-passwd --from-file=mosquitto_passwd="$DIR/mosquitto_passwd"
apply edge-01-secret \
  --from-file=fleetops_edge_device_secret="$DIR/edge-01.secret" \
  --from-file=fleetops_edge_api_token="$DIR/fleetops_edge_api_token" \
  --from-file=fleetops_edge_metrics_token="$DIR/fleetops_edge_metrics_token"
echo "secrets created in namespace $NS"
